            assert!(
                is_byte_exact_excluded(name),
                "{name} must pass through the lossless fold byte-exact"
            );
        }
        for name in ["Bash", "Grep", "WebFetch", "view", "headroom_retrieve"] {
            assert!(
                !is_byte_exact_excluded(name),
                "{name} must keep reaching the lossless fold"
            );
        }
    }
